include "globals.mzn";

enum COLOR = {Red, Green, Ivory, Yellow, Blue};
enum NATIONALITY = {Englishman, Spaniard, Ukranian, Norwegian, Japanese};
enum PET = {Dog, Snails, Fox, Horse, Zebra};
enum DRINK = {Coffee, Tea, Milk, OrangeJuice, Water};
enum CIGARETTE = {OldGold, Kools, Chesterfields, LuckyStrike, Parliaments};

array[1..5] of var COLOR: color;
array[1..5] of var NATIONALITY: nationality;
array[1..5] of var PET: pet;
array[1..5] of var DRINK: drink;
array[1..5] of var CIGARETTE: cigarette;

constraint
    nationality[1] = Norwegian /\
    drink[3] = Milk /\
    color[nationality.index(Englishman)] = Red /\
    pet[nationality.index(Spaniard)] = Dog /\
    drink[nationality.index(Ukranian)] = Tea /\
    color[nationality.index(Spaniard)] = pet[nationality.index(Spaniard)] /\
    color[nationality.index(Green)] = drink[nationality.index(Green)] /\
    color[nationality.index(Ivory)] + 1 = color[nationality.index(Green)] /\
    pet[nationality.index(OldGold)] = Snails /\
    cigarette[nationality.index(Kools)] = Yellow /\
    nationality.index(Chesterfields) + 1 = pet.index(Fox) \/
    nationality.index(Kools) + 1 = pet.index(Horse) /\
    drink[nationality.index(LuckyStrike)] = OrangeJuice /\
    cigarette[nationality.index(Japanese)] = Parliaments /\
    nationality.index(Norwegian) + 1 = color.index(Blue);

constraint alldifferent(color);
constraint alldifferent(nationality);
constraint alldifferent(pet);
constraint alldifferent(drink);
constraint alldifferent(cigarette);

include "globals.mzn";

enum COLOR = { Blue, Red, Green };
enum ANIMAL = { Dog, Cat, Zebra };

array[1..3] of var COLOR: color;
array[1..3] of var ANIMAL: animal;

constraint alldifferent(color);
constraint alldifferent(animal);
constraint animal[2] == Cat;
constraint color[2] == Red;
constraint color[1] == Blue;
constraint animal[1] == Dog;

include "globals.mzn";

enum Move = {Paper, Rock, Scissors};

var Move: youMove;
var Move: opponentMove;

