constraint youMove in Move;

solve satisfy;

include "globals.mzn";

enum Suspect = {Miss_Scarlett, Colonel_Mustard, Professor_Plum};
enum Weapon = {Candlestick, Revolver, Rope};
enum Room = {Kitchen, Library, Conservatory};

var Suspect: culprit;
var Weapon: murder_weapon;
var Room: murder_room;

constraint culprit != Colonel_Mustard;
constraint culprit != Miss_S Scarlett;
constraint murder_weapon != Revolver;
constraint murder_weapon != Rope;
constraint murder_room != Kitchen;
constraint murder_room != Library;

% Each suspect can only be the culprit once (implicitly satisfied as there is only one culprit)
% Each weapon can only be used once (implicitly satisfied as there is only one weapon)
% Each room can only host the murder once (implicitly satisfied as there is only one room)

solve satisfy;

include "globals.mzn";

enum CHARACTERS = {S, E, N, D, M, O, R, Y};

array[CHARACTERS] of var 0..9: digits;

% Constraints for the non-zero characters
constraint digits[S] in 1..9;
constraint digits[M] in 1..9;

% All characters must represent unique digits
constraint alldifferent(digits);

% Cryptarithmetic constraints
constraint 
    (digits[S] * 1000 + digits[E] * 100 + digits[N] * 10 + digits[D]) +
    (digits[M] * 1000 + digits[O] * 100 + digits[R] * 10 + digits[E]) =
    (digits[M] * 10000 + digits[O] * 1000 + digits N * 100 + digits[E] * 10 + digits[Y]);

% Carry constraints for each column
var int: carry1;
var int: carry2;
var int: carry3;

constraint 
    let {
        var int: sumDE = digits[D] + digits[E],
        var int: sumNR = digits[N] + digits[R] + carry1,
        var int: sumEO = digits[E] + digits[O] + carry2,
        var int: sumSM = digits[S] + digits[M] + carry3
    } in
    (sumDE mod 10 = digits[Y] /\ (sumDE >= 10 -> carry1 = 1 /\ carry1 = 0)) /\
    (sumNR mod 10 = digits[E] /\ (sumNR >= 10 -> carry2 = 1 /\ carry2 = 0)) /\
    (sumEO mod 10 = digits[N] /\ (sumEO >= 10 -> carry3 = 1 /\ carry3 = 0)) /\
    (sumSM mod 10 = digits[M] /\ (sumSM >= 10 -> carry4 = 1 /\ carry4 = 0));

include "globals.mzn";

enum Direction = {North, South, East, West};
enum Action = {crossing};

array[1..4] of var Direction: cars;
var Action: pedestrian;

constraint 
    (pedestrian = crossing) /\ 
    (cars[3] = East) /\ 
    (forall(i in 1..4)(cars[i] != cars[3])) /\ 
    (forall(i in 1..4)(cars[i] != pedestrian)) /\
    (cars[1] == North) /\ 
    (cars[2] == South) /\ 
    (cars[4] == West) /\

    let {
        var int: pedestrian_time = 1;
        var int: east_car_time = 1;
        var int: south_car_time = 0;
        var int: north_car_time = 2;
        var int: west_car_time = 2;
    } in
    (pedestrian_time < east_car_time) /\
    (pedestrian_time == east_car_time) /\
    (south_car_time < pedestrian_time) /\
    (north_car_time == west_car_time) /\
    (north_car_time > pedestrian_time);

include "globals.mzn";

enum Applicants = { Priya, Sam };
enum LoanStatus = { Approved, Denied, CounterOffer };

int: priyaCreditScore = 680;
int: samCreditScore = 750;
int: combinedMonthlyIncome = 9000;
int: combinedMonthlyDebt = 3200;
int: requestedLoanAmount = ...; % this amount is determined externally
int: policyLimit = ...; % this limit is determined externally

var int: lowerCreditScore = min(priyaCreditScore, samCreditScore);
var float: dtiRatio = combinedMonthlyDebt / (combinedMonthlyIncome * 1.0);

var LoanStatus: loanDecision;

constraint lowerCreditScore >= 600 -> loanDecision = Denied;
constraint dtiRatio > 0.43 -> loanDecision = Denied;

constraint (lowerCreditScore >= 600 /\ dtiRatio <= 0.43) -> (
    (requestedLoanAmount <= policyLimit -> loanDecision = Approved) /\
    (requestedLoanAmount > policyLimit -> loanDecision = CounterOffer)
);

include "globals.mzn";

enum TIME = { 9, 11, 16 };
enum DRUG = { A, B, C };

array[DRUG] of var TIME: drugTime;

% Constraints
constraint alldifferent(drugTime);
constraint drugTime[A] < drugTime[B]; % Drug B must be taken at least 4 hours after Drug A
constraint drugTime[B] >= drugTime[A] + 4;

% Drug C must be taken at least 2 hours away from any meal at 8am (8) and 1pm (13)
constraint (drugTime[C] < 8 + 2) \/ (drugTime[C] > 13 - 2);

