include "globals.mzn";

enum Color = { Red, Blue, Green, Yellow, Purple };
enum Animal = { Dog, Cat, Bird, Fish, Rabbit };
enum Food = { Pizza, Burger, Salad, Pasta, Ice Cream };

array[1..5] of var Color: favoriteColor;
array[1..5] of var Animal: favoriteAnimal;
array[1..5] of var Food: favoriteFood;

constraint alldifferent(favoriteColor);
constraint alldifferent(favoriteAnimal);
constraint alldifferent(favoriteFood);

constraint favoriteColor[1] != favoriteColor[2]; % Alice != Bob
constraint favoriteAnimal[3] != Dog; % Charlie's Favorite Animal is not a Dog
constraint favoriteFood[4] == Pizza; % David's Favorite Food is Pizza
constraint favoriteColor[5] == Blue; % Evelyn's Favorite Color is Blue
constraint favoriteAnimal[2] == Bird; % Bob's Favorite Animal is a Bird
constraint favoriteFood[3] != Salad; % Charlie's Favorite Food is not Salad
constraint forall(i in 1..5)(favoriteColor[i] != favoriteAnimal[i]); % No child has the same Favorite Color as their Favorite Animal

include "globals.mzn";

enum NEIGHBORS = {Ana, Bo, Cy};
enum HOUSES = 1..3;
enum LAUGH = {Loudest, Medium, Quiet};

array[NEIGHBORS] of var HOUSES: house;
array[NEIGHBORS] of var LAUGH: laugh;

constraint house[Ana] = 1;
constraint house[Bo] != 2;
constraint alldifferent(house);
constraint alldifferent(laugh);

include "globals.mzn";

enum Items = {rice, bookSet, skillet, firstAidKit, toolbox};

array[Items] of int: weights = [4, 3, 5, 2, 6];
array[Items] of int: values = [5, 4, 8, 6, 7];

array[Items] of var 0..1: itemSelection;

constraint sum([weights[i] * itemSelection[i] | i in Items]) <= 10;

constraint itemSelection[firstAidKit] == 1;

constraint forall(i in Items)(itemSelection[i] <= 1);

var int: totalValue = sum([values[i] * itemSelection[i] | i in Items]);

maximize totalValue;

include "globals.mzn";

enum Color = { Red, Blue, Green, Yellow, White };

array[1..5] of var Color: houseColor;

constraint houseColor[1] = Red;
constraint houseColor[4] = White;

constraint exists(i in 1..4)(houseColor[i] = Blue /\ houseColor[i+1] = Green);

constraint alldifferent(houseColor);

include "globals.mzn";

enum GroceryItem = { Ice_Cream, Canned_Beans, Bag_of_Flour, Bunch_of_Bananas };
array[1..4] of var GroceryItem: compartmentAssignment;

array[1..4] of int: compartments = [1, 2, 3, 4];

% Each grocery item is assigned to exactly one compartment
constraint forall(i in 1..4)(
    exists(j in 1..4)(compartmentAssignment[i] = GroceryItem[i] /\ compartmentAssignment[i] = j)
);

% The ice cream must be placed in Compartment 1
constraint compartmentAssignment[1] = Ice_Cream /\ compartmentAssignment[1] = 1;

solve satisfy;

include "globals.mzn";

enum Animal = {wolf, rabbit, goat, parrot, tortoise};
array[1..5] of var Animal: pen;

constraint pen[1] = tortoise;
constraint pen[2] = parrot;
constraint pen[3] = goat;
constraint exists(i in 1..5)(exists(j in (i+1)..5)(pen[i] = rabbit /\ pen[j] = wolf));
